(function(root){
'use strict';
const labels={reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking',shadowing:'Shadowing',habit:'Chuyên cần & Đúng hạn'};
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>Number.isFinite(v)?v.toLocaleString('vi-VN',{maximumFractionDigits:1}):'—';
const date=v=>{const d=new Date(v);return Number.isFinite(+d)?d.toLocaleDateString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit'}):'Chưa có hạn';};
const stamp=v=>{const d=new Date(v);return Number.isFinite(+d)?d.toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'';};
let options=null,weekOffset=0,summary=null,loadFailed=false,selected=false,timer=null,deferred=[];
function flushDeferred(){if(['planner','leaderboard'].includes(current().active))return;const work=deferred.splice(0);work.forEach(run=>run.start());}
function current(){return options?.getState?.()||{};}
function panel(tab){return document.getElementById('panel-'+tab);}
function setHtml(host,html){if(host.__studyHtml===html)return;host.__studyHtml=html;
 const change=()=>{host.innerHTML=html;};
 if(!host.hidden&&options?.preserve)options.preserve(change);else change();
}
function buildModel(){const state=current();return root.IeltsStudyPlannerModel.build({dashboard:state.dashboard,student:state.student,now:Date.now(),weekOffset,adapters:options.adapters});}
function planner(){const host=panel('planner'),state=current();if(!host||!state.dashboard||!state.student)return;const model=buildModel();setHtml(host,(root.Ielts48Master?.badge(model)||'')+root.Ielts48Experience.planner(model));bind(host);}
function overviewHtml(){const state=current();if(!state.student||!state.dashboard)return '';try{return (root.Ielts48Master?.overview(state.student)||'')+root.Ielts48Experience.overview(state,(summary?.entries||[]).find(e=>e.name===state.student.name),buildModel())+root.Ielts48Polish.trend(state.student);}catch(_){return '';}}
function componentValue(entry,key){const c=entry?.components?.[key];return typeof c==='number'?c:Number.isFinite(c?.score)?c.score:Number.isFinite(c?.value)?c.value:null;}
function recommendations(entry){const keys=['reading','listening','writing','speaking'],values=keys.map(key=>({key,value:componentValue(entry,key)})).filter(x=>x.value!==null).sort((a,b)=>a.value-b.value);if(!values.length)return '<p>Khi có đủ kết quả, em sẽ thấy kỹ năng cần ưu tiên tại đây. Trước mắt, hãy hoàn thành các bài trong thời gian biểu.</p>';
 const weakest=values[0];const advice={reading:'Sau mỗi passage, nhóm các câu sai theo dạng và chỉ ra dòng bằng chứng trước khi làm lại.',listening:'Nghe lại đoạn chứa câu sai, chép chính tả cụm ngắn và kiểm tra số nhiều, âm cuối.',writing:'Chọn một đoạn viết gần nhất, sửa theo nhận xét rồi viết lại để kiểm tra lỗi lặp.',speaking:'Luyện lại các nhóm lỗi trong nhận xét, thu một lượt nói ngắn và tự nghe trước khi nộp.'};
 return '<strong>Ưu tiên '+labels[weakest.key]+'</strong><p>'+advice[weakest.key]+'</p><button class="study-action" data-study-open="'+weakest.key+'">Mở bài '+labels[weakest.key]+' →</button>';
}
function leaderboard(){
 const host=panel('leaderboard'),state=current();if(!host||!state.student)return;
 const entries=summary?.entries||[],mine=entries.find(e=>e.name===state.student.name),ranked=entries.filter(e=>Number.isFinite(e.rank)),top=ranked.filter(e=>e.rank<=3),third=ranked[Math.min(2,ranked.length-1)],gap=mine&&third&&Number.isFinite(mine.total)?Math.max(0,third.total-mine.total):null;
 setHtml(host,'<div class="study-hub"><header class="study-heading"><div><p class="study-eyebrow">IELTS 48 · CÙNG NHAU TIẾN BỘ</p><h2>Xếp hạng lớp</h2><p>Ghi nhận kết quả học tập và thói quen hoàn thành bài đúng hạn.</p></div><div class="study-date">Cập nhật '+escape(stamp(summary?.generatedAt||summary?.capturedAt))+'</div></header>'+(summary?.sourceCoverage?.unavailable?'<p class="study-empty">'+summary.sourceCoverage.unavailable+' hồ sơ đang cập nhật, sẽ được xếp hạng khi đủ dữ liệu.</p>':'')+
 (!summary?'<div class="study-calm">'+(loadFailed?'Bảng lớp đang được cập nhật. Các tab bài tập vẫn hoạt động bình thường.':'Đang chuẩn bị bảng lớp…')+'</div>':
 '<section class="study-podium"><div class="study-section-title"><div><p class="study-eyebrow">BẢNG VÀNG</p><h3>Top 3 phong độ lớp</h3></div><span class="study-focus-note">'+ranked.length+' / '+entries.length+' học viên đủ dữ liệu</span></div>'+
 (top.length?'<div class="study-podium-grid">'+top.map((e,i)=>'<article class="study-winner place-'+Math.min(3,e.rank)+'"><span class="study-medal">'+['🥇','🥈','🥉'][Math.min(2,e.rank-1)]+'</span><small>HẠNG '+e.rank+'</small><h3>'+escape(e.name)+'</h3><strong>'+number(e.total)+'<em> / 100</em></strong>'+(e.provisional?'<span class="study-pill needs">Tạm tính</span>':'')+'</article>').join('')+'</div>':'<div class="study-calm">Chưa có đủ dữ liệu đồng nhất để công bố Top 3. Điểm thành phần đã có vẫn được hiển thị bên dưới.</div>')+'</section>'+
 '<section class="study-personal"><div class="study-personal-header"><div><p class="study-eyebrow">VỊ TRÍ CỦA EM</p><h3>'+escape(state.student.name)+'</h3></div><div class="study-rank">'+(mine?.rank?'#'+mine.rank:'—')+'<small>'+(mine?.rank?'trong '+ranked.length+' học viên':'Chờ đủ dữ liệu xếp hạng')+'</small></div></div><div class="study-personal-body"><div class="study-total"><span>Điểm tích lũy'+(mine?.provisional?' · tạm tính':'')+'</span><strong>'+number(mine?.total)+'<em>/100</em></strong><p>'+escape(gap===null?'Các thành phần chưa có điểm được để trống.':gap===0?'Em đang trong nhóm dẫn đầu. Hãy giữ nhịp học đều nhé!':'Cách Top 3: '+number(gap)+' điểm tích lũy.')+'</p></div><div class="study-components">'+Object.keys(labels).filter(k=>k!=='shadowing').map(k=>{const v=componentValue(mine,k);return '<div class="study-component"><div><span>'+escape(labels[k])+'</span><b>'+escape(root.Ielts48Experience.component(mine,k))+'</b></div><div class="study-track"><i style="width:'+Math.max(0,Math.min(100,v||0))+'%"></i></div><small>'+escape(v===null?'Chưa đủ dữ liệu':'Đóng góp '+number(v*.2)+' / 20 điểm')+'</small></div>';}).join('')+'</div></div></section>'+
 root.Ielts48Experience.explanation(mine,buildModel())+
 '<section class="study-advice"><div class="study-advice-icon" aria-hidden="true">↗</div><div><p class="study-eyebrow">BƯỚC TIẾP THEO</p>'+recommendations(mine)+'</div></section>'+
 '<section class="study-class-table"><div class="study-section-title"><div><h3>Phong độ cả lớp</h3><p>Bốn kỹ năng hiển thị Band theo bảng điểm; tổng tích lũy theo thang 100.</p></div></div><div class="study-table-scroll"><table><thead><tr><th>Hạng</th><th>Học viên</th><th>Reading</th><th>Listening</th><th>Writing</th><th>Speaking</th><th>Chuyên cần & Đúng hạn</th><th>Tổng</th></tr></thead><tbody>'+entries.map(e=>'<tr'+(e.name===state.student.name?' class="study-me" data-study-mine tabindex="0" aria-controls="study-personal-detail" aria-expanded="false"':'')+'><td>'+(e.rank||'—')+'</td><th scope="row">'+(e.name===state.student.name?'<span class="study-row-name">'+escape(e.name)+' · Em ↗</span>':escape(e.name))+'</th>'+['reading','listening','writing','speaking','habit'].map(k=>'<td>'+escape(root.Ielts48Experience.component(e,k))+'</td>').join('')+'<td><strong>'+number(e.total)+'</strong>'+(e.provisional?'<small>Tạm tính</small>':'')+'</td></tr>').join('')+'</tbody></table></div></section>'+
 '<details data-history-section="study-method" class="study-method"><summary>Cách tính điểm & nguồn kết quả</summary><p>Điểm tổng = 20% Reading + 20% Listening + 20% Writing + 20% Speaking + 20% Shadowing & đúng hạn.</p><p>Bốn kỹ năng dùng kết quả kiểm tra cùng đợt của lớp, quy đổi Band ÷ 9 × 100. Thành phần thói quen gồm 50% hoàn thành Shadowing và 50% nộp bài đúng hạn, trong 8 tuần gần nhất. Đây là điểm học tập của lớp, không phải IELTS Overall Band.</p><p>'+escape('Chỉ dùng '+(summary?.scope?.habit?.includedAssignmentCodes||0)+' bài có đủ xác nhận trong phạm vi chung của cả lớp. '+(summary?.scope?.habit?.excludedAssignmentCodes||0)+' bài chưa đủ xác nhận được tạm loại cho toàn lớp, không tính là điểm 0.')+'</p><p>'+['reading','listening','writing','speaking'].map(key=>escape(labels[key]+': '+(summary?.scope?.[key]?.sourceLabel||'Chưa có kết quả')+' · '+(summary?.scope?.[key]?.sourceDate||'Chưa có ngày'))).join('<br>')+'</p><p>Bảng lớp cập nhật định kỳ; trạng thái bài nộp trong các tab kỹ năng và thời gian biểu vẫn tự đồng bộ như trước.</p></details>')+'</div>');
 bind(host);
}
const boundStudyButtons=new WeakSet();
function bind(host){root.Ielts48Experience.bind(host);host.querySelectorAll('[data-study-week]').forEach(b=>{if(boundStudyButtons.has(b))return;boundStudyButtons.add(b);b.addEventListener('click',()=>{const v=Number(b.dataset.studyWeek);weekOffset=v===0?0:weekOffset+v;planner();});});host.querySelectorAll('[data-study-open]').forEach(b=>{if(boundStudyButtons.has(b))return;boundStudyButtons.add(b);b.addEventListener('click',()=>options.activate(b.dataset.studyOpen));});}
async function refreshSummary(){try{const r=await fetch('./data/academic-leaderboard.json',{cache:'no-cache',signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error('SUMMARY_UNAVAILABLE');const data=await r.json();if(data.schemaVersion!==1||data.className!=='IELTS 48'||!Array.isArray(data.entries))throw Error('INVALID_SUMMARY');const changed=JSON.stringify(data)!==JSON.stringify(summary);summary=data;loadFailed=false;if(changed&&current().active==='leaderboard')leaderboard();if(changed&&current().active==='overview')options.preserve(()=>options.activate('overview'));}catch(_){loadFailed=true;if(current().active==='leaderboard'&&!summary)leaderboard();}}
function render(tab){if(tab==='planner'){planner();return true;}if(tab==='leaderboard'){leaderboard();return true;}flushDeferred();return false;}
function install(value){if(options)return;options=value;const data=document.getElementById('ielts48-academic-seed');try{summary=JSON.parse(data?.textContent||'null');}catch(_){}
 const statusCache=new Map(),readStatus=options.adapters.status;
 options.adapters.status=item=>{const state=current(),key=[state.student?.name,state.dashboard?.parentRosterRevision,item.id].join('|'),value=readStatus(item),previous=statusCache.get(key);if(value.confirmed===true){statusCache.set(key,{value,at:Date.now()});return value;}return previous&&Date.now()-previous.at<30000?previous.value:value;};
 const originalRequest=options.access.request;options.access.request=function(action,...args){
  if(['planner','leaderboard'].includes(current().active)&&['writing','classwork_index','writing_assessment'].includes(action))return new Promise((resolve,reject)=>deferred.push({start:()=>Promise.resolve(originalRequest.call(options.access,action,...args)).then(resolve,reject),reject}));
  return originalRequest.call(options.access,action,...args);
 };
 window.addEventListener('hashchange',()=>{deferred.splice(0).forEach(item=>item.reject(Object.assign(Error('SESSION_ENDED'),{code:'SESSION_ENDED'})));});
 options.wrapTab(render);options.wrapRefresh(()=>{if(['planner','leaderboard'].includes(current().active))render(current().active);});
 const requested=new URLSearchParams(location.search).get('view');if(['planner','leaderboard'].includes(requested)){current().active=requested;selected=true;}
 refreshSummary();timer=setInterval(()=>{if(document.hidden)return;if(current().active==='planner')planner();refreshSummary();},60000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(current().active==='planner')planner();refreshSummary();}});
}
root.IeltsStudyHub={install,render,refreshSummary,overviewHtml,model:buildModel,openNextWeek:()=>{weekOffset=1;options.activate('planner');},pendingTasks:()=>buildModel().tasks.filter(t=>t.status!=='done'),openTask:t=>{if(root.Ielts48Master){root.Ielts48Master.openPending(t);return;}options.activate(t.skill);},useStatus:fn=>{options.adapters.status=fn;}};
})(globalThis);
